/**
 * @name Untrusted image data reaching image decoders
 * @description Detect flows from remote/user-controlled sources into Pillow image loading/decoding APIs, which may expose memory corruption or DoS in native decoders.
 * @kind path-problem
 * @problem.severity error
 * @id py/pillow-untrusted-image-decode
 * @tags security
 *       external/cwe/cwe-020
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs
import semmle.python.Concepts

module PillowImageDecodeConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call, DataFlow::Node argNode |
      // PIL.Image.open(...)
      call = API::moduleImport("PIL").getMember("Image").getMember("open").getACall() or
      // PIL.Image.frombytes/frombuffer
      call = API::moduleImport("PIL").getMember("Image").getMember(["frombytes", "frombuffer"]).getACall() or
      // Image.Image.load (instance method)
      call = API::moduleImport("PIL").getMember("Image!").getMember("load").getACall()
      |
      argNode = call.getArg(0) and
      sink = argNode
    )
  }
}

module PillowImageDecodeFlow = TaintTracking::Global<PillowImageDecodeConfig>;
import PillowImageDecodeFlow::PathGraph

from PillowImageDecodeFlow::PathNode source, PillowImageDecodeFlow::PathNode sink
where PillowImageDecodeFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Untrusted data flows into Pillow image decoding API $@.", source.getNode(), "user-controlled data"

/**
 * @name Subprocess execution in Pillow
 * @description Detect uses of subprocess or os.system that may be influenced by external input.
 * @kind path-problem
 * @problem.severity error
 * @id py/pillow-subprocess-taint
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module PillowSubprocessConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call, DataFlow::Node arg |
      // subprocess.*
      call = API::moduleImport("subprocess").getMember(["call", "check_call", "check_output", "run", "Popen"]).getACall() or
      // os.system, os.popen
      call = API::moduleImport("os").getMember(["system", "popen"]).getACall()
      |
      arg = call.getArg(0) and
      sink = arg
    )
  }
}

module PillowSubprocessFlow = TaintTracking::Global<PillowSubprocessConfig>;
import PillowSubprocessFlow::PathGraph

from PillowSubprocessFlow::PathNode source, PillowSubprocessFlow::PathNode sink
where PillowSubprocessFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data flows into subprocess or os command execution $@.", source.getNode(), "user input"
